\copy (SELECT p."companyId" AS company_id, p.id AS prestation_id, p.nom AS prestation, p.actif AS prestation_actif, op.id AS option_id, op.nom AS option, co.id AS choix_id, co.nom AS choix, co.actif AS choix_actif FROM prestations p LEFT JOIN options_prestations op ON op."prestationId" = p.id LEFT JOIN choix_options co ON co."optionId" = op.id ORDER BY p.id, op.id, co.id) TO '/tmp/export_catalogue.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')